use proptest::prelude::*;

use super::*;

/// A term as the user would write it: the text before escaping, so that a literal's `pattern` is its escape.
#[derive(Debug, Clone)]
enum Written {
    Literal(Modifier, String),
    Regex(String),
}

// No backslash: `\"` is the only escape, so a backslash next to a quote has no faithful rendering.
fn text() -> impl Strategy<Value = String> {
    "[a-zA-Z0-9 .*+?()\\[\\]{}|^$:\"-]{0,12}"
}

fn written() -> impl Strategy<Value = Written> {
    prop_oneof![
        (prop_oneof![Just(Modifier::Required), Just(Modifier::Excluded), Just(Modifier::Optional)], text())
            .prop_map(|(modifier, text)| Written::Literal(modifier, text)),
        // A modifier before `regex:` is dropped by the parser, so a regex term is always optional.
        text().prop_map(Written::Regex),
    ]
}

fn render(terms: &[Written]) -> String {
    let quote = |text: &str| format!("\"{}\"", text.replace('"', "\\\""));
    let rendered: Vec<String> = terms
        .iter()
        .map(|term| match term {
            Written::Literal(Modifier::Required, text) => format!("+{}", quote(text)),
            Written::Literal(Modifier::Excluded, text) => format!("-{}", quote(text)),
            Written::Literal(Modifier::Optional, text) => quote(text),
            Written::Regex(text) => format!("regex:{}", quote(text)),
        })
        .collect();
    rendered.join(" ")
}

fn expected(terms: &[Written]) -> Vec<(Modifier, String, bool)> {
    terms
        .iter()
        .map(|term| match term {
            Written::Literal(modifier, text) => (modifier.clone(), regex::escape(text), false),
            Written::Regex(text) => (Modifier::Optional, text.clone(), true),
        })
        .collect()
}

proptest! {
    #[test]
    fn parse_never_panics_on_arbitrary_text(input in "\\PC{0,80}") {
        drop(parse(&input));
    }

    #[test]
    fn parse_never_panics_on_query_shaped_text(input in "(\\+|-|regex:|\"|\\\\|[a-z.]| )*") {
        drop(parse(&input));
    }

    #[test]
    fn parse_of_rendered_terms_recovers_the_terms(terms in prop::collection::vec(written(), 0..=64)) {
        let parsed = parse(&render(&terms)).expect("at most 64 terms");
        let parsed: Vec<_> = parsed.into_iter().map(|t| (t.modifier, t.pattern, t.is_regex)).collect();
        prop_assert_eq!(parsed, expected(&terms));
    }
}
//! Black-box tests for the query language and file filters, against throwaway project trees.
#![cfg(feature = "cli")]
#![allow(clippy::unwrap_used, clippy::expect_used, reason = "a failing assertion should panic in a test")]

use std::fs;
use std::process::Command;

/// Writes `files` to a tempdir, runs `monokl search <args>` there and returns the sorted `src/` file names printed.
fn matched(files: &[(&str, &str)], args: &[&str]) -> Vec<String> {
    let dir = tempfile::tempdir().unwrap();
    for (name, body) in files {
        let path = dir.path().join(name);
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(path, body).unwrap();
    }
    let output =
        Command::new(env!("CARGO_BIN_EXE_monokl")).arg("search").args(args).current_dir(dir.path()).output().unwrap();
    let text = String::from_utf8(output.stdout).unwrap();
    let mut names: Vec<String> = text
        .lines()
        .filter_map(|line| line.trim_start().split(',').next())
        .filter(|name| name.starts_with("src/"))
        .map(str::to_owned)
        .collect();
    names.sort();
    names.dedup();
    names
}

const TWO_FILES: [(&str, &str); 2] =
    [("src/a.ts", "export function bar() { return foo; }\n"), ("src/b.ts", "export function bar() { return 1; }\n")];

#[test]
fn minus_regex_excludes_files() {
    assert_eq!(matched(&TWO_FILES, &["bar -regex:foo", "."]), ["src/b.ts"]);
}

#[test]
fn plus_regex_requires_files() {
    assert_eq!(matched(&TWO_FILES, &["bar +regex:foo", "."]), ["src/a.ts"]);
}

#[test]
fn quoted_regex_pattern_may_contain_spaces() {
    let files = [("src/a.ts", "export function useThing() {}\n"), ("src/b.ts", "export const useThing = 1;\n")];
    assert_eq!(matched(&files, &["regex:\"function use[A-Z]\"", "."]), ["src/a.ts"]);
}

#[test]
fn language_flag_selects_by_extension() {
    let files = [("src/a.ts", "const alpha = 1;\n"), ("src/b.js", "const alpha = 1;\n")];
    assert_eq!(matched(&files, &["alpha", ".", "--language", "typescript"]), ["src/a.ts"]);
    assert_eq!(matched(&files, &["alpha", ".", "--language", "javascript"]), ["src/b.js"]);
}

