        ("src/v.spec.cts", "const alpha = 1;\n"),
    ];
    assert_eq!(matched(&files, &["alpha", "."]), ["src/a.ts"]);
}

input.new_string:
    assert_eq!(matched(&files, &["alpha", "."]), ["src/a.ts"]);
}

#[test]
fn empty_phrase_is_ignored() {
    assert_eq!(matched(&TWO_FILES, &["foo \"\"", "."]), ["src/a.ts"]);
    assert_eq!(matched(&TWO_FILES, &["\"\"", "."]), Vec::<String>::new());
}
